-- TRIPSPHERE reference data — attractions (part 1)
INSERT OR IGNORE INTO attractions
(slug, destination_id, name, category, summary, description, image, lat, lng, opening_hours, entry_fee, avg_visit_minutes, rating, reviews_count, is_hidden, unesco, tips) VALUES
('virupaksha-temple',1,'Virupaksha Temple','temple','A working 7th-century temple at the heart of Hampi bazaar.','Still active after more than a thousand years, Virupaksha is dedicated to Shiva and anchors the old bazaar street. The gopuram is best photographed in early morning light, and the temple elephant is usually at the river gate.','/images/hampi.jpg',15.3352,76.4592,'6:00 AM - 8:00 PM',0,60,4.6,2480,0,1,'Remove footwear before entering; mornings are quietest.'),
('vijaya-vittala-temple',1,'Vijaya Vittala Temple and Stone Chariot','heritage','Hampi''s most ornate temple complex, home of the stone chariot.','The Vittala complex holds the famous stone chariot and the musical pillars. Allow a full hour to walk the halls and the ruined bazaar approach, and bring water — shade is limited.','/images/hampi.jpg',15.3426,76.4752,'6:00 AM - 6:00 PM',35,90,4.7,3120,0,1,'Tickets are sold online and at the gate; sunset light is exceptional.'),
('matanga-hill',1,'Matanga Hill Sunrise Point','nature','The highest point in Hampi with a 360-degree view of the ruins.','A short, steep climb above the bazaar leads to the best sunrise in the valley. The Tungabhadra river, temple towers and boulder fields all line up below you. Carry a torch if you climb before dawn.','/images/hampi.jpg',15.3347,76.4726,'Open all day',0,75,4.6,940,1,0,'Go with a local guide before sunrise; the path is unlit.'),
('anegundi-village',1,'Anegundi Village','cultural','A quiet riverside village with coracle rides and old forts.','Across the Tungabhadra from Hampi, Anegundi is greener, slower and full of small guesthouses. Take a coracle across the river, cycle through banana fields, and stop at the old palace and Hanuman temple.','/images/hampi.jpg',15.3516,76.4880,'Open all day',0,120,4.4,410,1,0,'Coracles cost about 100 rupees per person; negotiate before boarding.'),
('mysore-palace',2,'Mysore Palace','heritage','The Indo-Saracenic royal palace at the centre of the city.','The Amba Vilas Palace is the city''s defining building, with painted durbar halls and a courtyard that glows under 100,000 lights on Sunday evenings. Audio guides give the history real shape.','/images/jaipur.jpg',12.3052,76.6551,'10:00 AM - 5:30 PM',200,120,4.6,8600,0,0,'Sunday illumination runs 7:00 - 8:00 PM; arrive early for the queue.'),
('chamundeshwari-temple',2,'Chamundeshwari Temple','temple','A hilltop temple with steps, views and a giant Nandi.','Climb the thousand steps or drive up to this Shakti temple on Chamundi Hill. The Nandi statue on the way is one of the largest in India, and the city opens up below at dusk.','/images/jaipur.jpg',12.2724,76.6706,'7:30 AM - 6:00 PM',0,75,4.5,3900,0,0,'Dress modestly; the steps are crowded on Fridays and weekends.'),
('brindavan-gardens',2,'Brindavan Gardens','nature','Terraced gardens below the KRS dam with a musical fountain.','Laid out below the Krishna Raja Sagara dam, Brindavan is at its best in the late afternoon. The musical fountain runs every evening, and the terraces are a good picnic stop with children.','/images/munnar.jpg',12.3065,76.6292,'6:00 AM - 8:00 PM',100,90,4.1,5200,0,0,'Musical fountain show is around 6:30 PM; confirm timings locally.'),
('devaraja-market',2,'Devaraja Market','cultural','A working market of flowers, silk, spices and sandalwood.','Hundreds of small stalls sell jasmine garlands, kumkum, bananas and silk by the metre. It is the most alive place in Mysore and a photographer''s playground in the first hour after opening.','/images/food.jpg',12.3079,76.6540,'6:00 AM - 9:00 PM',0,45,4.4,1100,1,0,'Ask before photographing shopkeepers; mornings smell of fresh jasmine.'),
('abbey-falls',3,'Abbey Falls','waterfall','A short forest walk to a monsoon-fed cascade.','A paved path through coffee and cardamom bushes leads to the falls viewpoint. The water is heaviest just after the rains, and the spray keeps the surrounding forest cool.','/images/coorg.jpg',12.3550,75.8060,'8:00 AM - 6:00 PM',30,45,4.2,2600,0,0,'Slippery steps in monsoon; avoid swimming in the pool.'),
('rajas-seat',3,'Raja''s Seat','nature','A garden viewpoint over the Coorg valley.','This terraced garden was the summer retreat of the Kodagu kings. Sunset over the valley is the draw, with a small musical fountain and plenty of benches for a slow half hour.','/images/coorg.jpg',12.4210,75.7380,'8:00 AM - 8:00 PM',10,45,4.2,3100,0,0,'Come 45 minutes before sunset for a seat at the railing.'),
('dubare-elephant-camp',3,'Dubare Elephant Camp','wildlife','A riverside camp where you can learn about rescued elephants.','Dubare sits on the Kaveri river and runs feeding and bathing sessions with camp elephants. It is popular with families, so arrive at opening time to avoid the crowd.','/images/wildlife.jpg',12.3900,75.9200,'9:00 AM - 5:00 PM',400,120,4.3,2900,0,0,'Book the interaction slot in advance during peak season.'),
('mandalpatti-viewpoint',4,'Mandalpatti Viewpoint','nature','A jeep track to a ridge with cloud-level views.','The last stretch is a rough jeep trail, which is half the fun. From the top, the Western Ghats roll away in layers, and on a clear morning the mist sits below you.','/images/coorg.jpg',12.3900,75.7200,'6:00 AM - 6:00 PM',0,120,4.5,1600,1,0,'Hire a local jeep at Madikeri; do not attempt the track in a hatchback.'),
('mullayanagiri-peak',4,'Mullayanagiri Peak','adventure','The highest peak in Karnataka, with a temple at the summit.','A short but steep climb from the road head takes you to 1,930 metres and a small shrine. Sunrise and sunset both work, but the wind is constant — bring a layer.','/images/munnar.jpg',13.3906,75.7212,'6:00 AM - 6:00 PM',50,90,4.6,2200,0,0,'Drive to the base early; parking fills by 8 AM on weekends.'),
('hebbe-falls',4,'Hebbe Falls','waterfall','A two-stage waterfall reached through a coffee estate.','Hebbe is hidden inside a private estate near Kemmangundi. A shared jeep covers the first section, then a forest walk leads to the lower pool. Best flow is between July and January.','/images/coorg.jpg',13.4167,75.6833,'7:00 AM - 5:00 PM',400,150,4.4,1900,1,0,'Entry is limited; book at the estate gate and carry cash.'),
('coffee-estate-walk',4,'Estate Coffee Walk','cultural','Learn how Indian coffee is grown, picked and roasted.','Several estates around Chikmagalur run guided walks through the coffee blocks, ending with a cupping session. It is a relaxed, informative two hours and good in any weather.','/images/coorg.jpg',13.3161,75.7720,'8:00 AM - 5:00 PM',350,90,4.5,620,1,0,'Book a day ahead; harvest season runs November to January.'),
('om-beach',5,'Om Beach','beach','A twin-cove beach shaped like the Om symbol.','Om Beach is the most social of Gokarna''s beaches, with shacks, surf schools and a cliff path to Kudle. The water is calm enough for a swim in season.','/images/goa.jpg',14.5206,74.3139,'Open all day',0,150,4.5,4800,0,0,'Currents pick up in monsoon; swim only where locals do.'),
('mahabaleshwar-temple',5,'Mahabaleshwar Temple','temple','An ancient Shiva temple in the middle of Gokarna town.','The town''s spiritual centre, with a carved stone gateway and daily ritual. Visit early in the morning to see the temple at its most active, then walk down to the main beach.','/images/hampi.jpg',14.5489,74.3167,'6:00 AM - 8:00 PM',0,40,4.3,1500,0,0,'Men remove shirts before entering the inner sanctum.'),
('paradise-beach',5,'Paradise Beach','beach','A small cove reached by a cliff trail or fishing boat.','Paradise is quieter than Om and has no permanent buildings. Walk the cliff path at low tide, or take a short boat from Om Beach. Carry water and leave no waste.','/images/goa.jpg',14.5167,74.3000,'Open all day',0,120,4.6,1300,1,0,'The trail is tidal; check the tide before setting out.'),
('kabini-safari',6,'Kabini Wildlife Safari','wildlife','Dawn and dusk jeep safaris through Nagarhole.','Forest department jeeps and canter safaris run twice a day into the Nagarhole range. Elephants, gaur and — if you are lucky — leopard and tiger are the headline sightings.','/images/wildlife.jpg',11.9167,76.1833,'6:00 AM - 9:00 AM, 3:00 PM - 6:00 PM',1500,180,4.6,2100,0,0,'Book through your stay; mornings have better sighting odds.'),
('nagarhole-national-park',6,'Nagarhole National Park','wildlife','A vast protected forest of teak, bamboo and big cats.','Nagarhole forms the core of the Nilgiri biosphere reserve. Safaris are strictly regulated, and the buffer zone around Kabini is where most sightings happen.','/images/wildlife.jpg',12.0500,76.2000,'6:00 AM - 6:00 PM',1200,240,4.5,1800,0,0,'Carry binoculars, neutral colours and no strong perfume.'),
('kabini-sunset-point',6,'Kabini Backwaters Sunset','nature','A quiet reservoir edge for the last hour of light.','The Kabini reservoir draws animals to the water at dusk. A boat safari or a riverside deck both work; the point is to stop moving and watch the far bank.','/images/wildlife.jpg',11.9100,76.1700,'4:30 PM - 6:30 PM',0,60,4.4,760,1,0,'Boat safaris sell out in peak season; reserve a day ahead.'),
('eravikulam-national-park',7,'Eravikulam National Park','wildlife','A high-altitude park protecting the Nilgiri tahr.','A shuttle bus and a short trail take you through shola grassland where Nilgiri tahr graze. The park closes during the calving season, usually February to April.','/images/munnar.jpg',10.1500,77.0833,'7:30 AM - 4:00 PM',200,120,4.5,6100,0,1,'Tickets are timed; book the first slot for clear views.'),
('mattupetty-dam',7,'Mattupetty Dam','nature','A reservoir with boat rides and tea stalls on the shore.','Mattupetty is an easy stop on the Munnar loop, with pedal boats and a view of the tea slopes. The nearby dairy farm is a good add-on for families.','/images/munnar.jpg',10.1000,77.1333,'9:00 AM - 5:00 PM',50,75,4.1,3400,0,0,'Go before 10 AM; mist often hides the far shore later.'),
('top-station',7,'Top Station','nature','The ridge viewpoint over the Western Ghats.','On a clear day Top Station shows the whole valley down to the Tamil Nadu plains. Early morning is the only reliable window before cloud rolls in.','/images/munnar.jpg',10.1167,77.2333,'6:00 AM - 6:00 PM',40,75,4.5,2800,0,0,'Carry a jacket; the ridge is windy and 10 degrees cooler.'),
('tea-museum',7,'Tea Museum and Factory','cultural','A working tea museum that explains the whole leaf-to-cup process.','The Kannan Devan museum walks you through rolling, drying and grading, with a tasting at the end. It is a good rainy-day stop and takes about an hour.','/images/munnar.jpg',10.0889,77.0595,'9:00 AM - 5:00 PM',150,60,4.2,1900,0,0,'The factory is quiet on Sundays; check before visiting.'),
('alleppey-houseboat',8,'Backwater Houseboat Cruise','nature','A slow cruise through the Kuttanad canals and paddy fields.','A houseboat or shikara cruise is the defining Alleppey experience. Routes pass village landings, toddy shops and wide paddy fields, with meals cooked on board by the crew.','/images/kerala.jpg',9.4981,76.3388,'9:00 AM - 6:00 PM',4500,300,4.6,5200,0,0,'Book through licensed operators; overnight cruises leave by noon.'),
('alappuzha-beach',8,'Alappuzha Beach','beach','A town beach with a pier and evening food stalls.','The beach is not the region''s best, but the pier, the lighthouse and the sea breeze make it a pleasant hour before dinner. The Nehru trophy boat race is held here in August.','/images/kerala.jpg',9.4833,76.3167,'Open all day',0,60,4.1,2600,0,0,'Best at sunset; the pier closes after dark.'),
('marari-beach',8,'Marari Beach','beach','A quiet fishing beach lined with coconut palms.','Marari is where Alleppey comes to do nothing. Fishermen bring in the catch in the morning, homestays serve fresh fish, and the beach stays empty on weekdays.','/images/goa.jpg',9.6167,76.2833,'Open all day',0,150,4.5,1700,1,0,'Swim near the lifeguard flags; the undertow can be strong.'),
('basilica-bom-jesus',9,'Basilica of Bom Jesus','heritage','A UNESCO-listed baroque church holding the relics of St Francis Xavier.','Built in 1605, the basilica is the finest example of baroque architecture in India. The gilded altar and the silver casket are the highlights; allow time for the adjoining convent museum.','/images/jaipur.jpg',15.5009,73.9116,'9:00 AM - 6:30 PM',0,60,4.5,7200,0,1,'Shoulders and knees covered; Sunday mass limits tourist access.'),
('palolem-beach',9,'Palolem Beach','beach','A crescent bay of calm water and palm shacks.','Palolem is the most photogenic beach in south Goa, with a shallow bay that suits swimming and kayaking. The quieter northern end has the better sunsets.','/images/goa.jpg',15.0100,74.0233,'Open all day',0,180,4.5,8400,0,0,'Park at the north entrance to avoid the main-road crush.'),
('dudhsagar-falls',9,'Dudhsagar Falls','waterfall','A four-tiered waterfall reached by jeep through the forest.','Dudhsagar drops 310 metres inside Bhagwan Mahaveer sanctuary. Access is by forest jeep from Kulem, and the pool is closed during heavy monsoon flow.','/images/coorg.jpg',15.3167,74.3167,'7:00 AM - 5:00 PM',400,240,4.4,6900,0,0,'Book the official jeep at Kulem; private cars cannot enter.'),
('fontainhas-quarter',9,'Fontainhas Latin Quarter','cultural','Panaji''s Portuguese-era lanes of ochre and blue villas.','Fontainhas is best explored on foot, with stops at small bakeries and galleries. The lanes are narrow, the balconies are painted, and the whole area takes about ninety minutes.','/images/food.jpg',15.4989,73.8278,'Open all day',0,90,4.4,2400,1,0,'Start at the chapel of St Sebastian and wander downhill.'),
('amber-fort',10,'Amber Fort','heritage','A hilltop Rajput fort of mirrored halls and courtyards.','Amber Fort sits above Maota Lake and holds the Sheesh Mahal, the Hall of Public Audience and long ramparts. Go at opening time to beat the tour groups, then walk down to the old stepwell.','/images/jaipur.jpg',26.9855,75.8513,'8:00 AM - 5:30 PM',500,150,4.7,18400,0,1,'The composite ticket covers five monuments over two days.'),
('hawa-mahal',10,'Hawa Mahal','heritage','The pink palace of 953 latticed windows.','Built so the royal women could watch the street unseen, Hawa Mahal is best seen from the cafe opposite at sunrise. Entry takes you up through narrow ramps to the jharokha windows.','/images/jaipur.jpg',26.9239,75.8267,'9:00 AM - 4:30 PM',50,60,4.4,9600,0,0,'Photograph from the rooftop cafe across the road for the full facade.'),
('city-palace-jaipur',10,'City Palace Jaipur','heritage','The royal residence, with courtyards, armouries and textiles.','The City Palace is still partly occupied by the royal family. The Mubarak Mahal textile gallery and the silver urns in the Diwan-i-Khas are the highlights of a two-hour visit.','/images/jaipur.jpg',26.9258,75.8237,'9:00 AM - 5:00 PM',700,120,4.5,7800,0,0,'Buy the combined ticket if you also plan to see Amber and Jantar Mantar.'),
('panna-meena-ka-kund',10,'Panna Meena ka Kund','heritage','A symmetrical stepwell with a staircase that looks impossible.','This 16th-century stepwell is a short drive from Amber Fort and far quieter. The criss-cross stairs are a photographer''s favourite; the site is small and needs twenty minutes.','/images/hampi.jpg',26.9950,75.8530,'7:00 AM - 6:00 PM',0,30,4.3,1200,1,0,'Locals ask visitors not to descend the steps; view from the rim.'),
('city-palace-udaipur',11,'City Palace Udaipur','heritage','A lakeside palace of courtyards, mosaics and lake views.','The largest palace complex in Rajasthan rises above Lake Pichola in layers. The Mor Chowk peacock mosaics and the lake-facing terraces are the high points of a two-hour walk.','/images/jaipur.jpg',24.5764,73.6835,'9:30 AM - 5:30 PM',400,120,4.6,5400,0,0,'The Crystal Gallery needs a separate ticket and is worth it.'),
('lake-pichola',11,'Lake Pichola Boat Ride','nature','A sunset boat between the lake palaces.','Boats leave from Rameshwar Ghat for a slow loop past Jag Mandir and the Taj lake palace. Sunset trips are the most popular and sell out early in the day.','/images/jaipur.jpg',24.5720,73.6800,'10:00 AM - 6:00 PM',400,60,4.6,4600,0,0,'Book the 5 PM slot for golden light; carry a light layer.'),
('sajjangarh-monsoon-palace',11,'Sajjangarh Monsoon Palace','heritage','A hill palace built to watch the monsoon arrive.','The palace sits on a ridge outside the city with a wide view over the Aravallis and the lakes. Sunset is the reason to come, and the road up is a series of tight bends.','/images/jaipur.jpg',24.5930,73.6400,'8:00 AM - 6:00 PM',300,75,4.3,3200,0,0,'Arrive an hour before sunset; the viewpoint gets crowded.'),
('bagore-ki-haveli',11,'Bagore ki Haveli','cultural','A restored haveli staging Rajasthani folk performances.','The evening dance and puppet show on the lake-facing terrace is the reason most travellers come. Arrive early for a front seat, and walk the museum rooms beforehand.','/images/jaipur.jpg',24.5785,73.6820,'10:00 AM - 8:00 PM',150,90,4.4,2900,0,0,'Show starts at 7 PM; tickets at the gate from 6 PM.');
